-- Generated by scripts/seed-json.mjs. Safe to re-run.
-- Requires: create extension if not exists http with schema extensions;
create temp table seed_doc on commit drop as
select content::jsonb as d from extensions.http_get('https://raw.githubusercontent.com/bizzybae/dr-mushtaqs-blackseed/main/supabase/seed.json?v=1791691927430');

insert into public.collections (slug, name, short_label, description, hero_image_url, steps, sort_order, is_published)
select x.slug, x.name, x.short, x.description, x.hero, array(select jsonb_array_elements_text(x.steps)), x.sort, true
from seed_doc, jsonb_to_recordset(d->'collections') as x(slug text, name text, short text, description text, hero text, steps jsonb, sort int)
on conflict (slug) do update set name = excluded.name, short_label = excluded.short_label, description = excluded.description, hero_image_url = excluded.hero_image_url, steps = excluded.steps, sort_order = excluded.sort_order, is_published = true;

insert into public.botanicals (key, name, latin, part, origin, ayurveda, unani, tcm, note)
select x.key, x.name, x.latin, x.part, x.origin, x.ayurveda, x.unani, x.tcm, x.note
from seed_doc, jsonb_to_recordset(d->'botanicals') as x(key text, name text, latin text, part text, origin text, ayurveda text, unani text, tcm text, note text)
on conflict (key) do update set name = excluded.name, latin = excluded.latin, part = excluded.part, origin = excluded.origin, ayurveda = excluded.ayurveda, unani = excluded.unani, tcm = excluded.tcm, note = excluded.note;

insert into public.products (slug, status, name, subtitle, tagline, category, product_type, short_description, long_description, inci_ingredients, is_featured, is_new, is_bestseller, is_published, sort_order, badges, specs, collection_slug, step, botanicals, mosaic, seo_title, seo_description,
  intended_use, sensory_line, sensory_notes, storage, shelf_life, serving, serving_ml, directions, how_to)
select x.slug, x.status, x.name, x.subtitle, x.tagline, x.category, x.type, x.short, x.long, x.ingredients, x.featured, x."isNew", x.bestseller, true, x.sort,
  array(select jsonb_array_elements_text(d->'badges')), x.specs, x.collection, x.step,
  array(select jsonb_array_elements_text(x.botanicals)), array(select jsonb_array_elements_text(x.mosaic)), x.name || ' | Dr. Mushtaq’s', x.short,
  x."intendedUse", x."sensoryLine", x.sensory, x.storage, x."shelfLife", x.serving, x."servingMl", array(select jsonb_array_elements_text(x.directions)), x."howTo"
from seed_doc, jsonb_to_recordset(d->'products') as x(slug text, status text, name text, subtitle text, tagline text, category text, type text, short text, long text, ingredients text, featured bool, "isNew" bool, bestseller bool, sort int, specs jsonb, collection text, step text, botanicals jsonb, mosaic jsonb,
  "intendedUse" text, "sensoryLine" text, sensory text, storage text, "shelfLife" text, serving text, "servingMl" numeric, directions jsonb, "howTo" jsonb)
on conflict (slug) do update set status = excluded.status, name = excluded.name, subtitle = excluded.subtitle, tagline = excluded.tagline, category = excluded.category, product_type = excluded.product_type,
  short_description = excluded.short_description, long_description = excluded.long_description, inci_ingredients = excluded.inci_ingredients, is_featured = excluded.is_featured, is_new = excluded.is_new,
  is_bestseller = excluded.is_bestseller, is_published = true, sort_order = excluded.sort_order, badges = excluded.badges, specs = excluded.specs, collection_slug = excluded.collection_slug, step = excluded.step,
  botanicals = excluded.botanicals, mosaic = excluded.mosaic, seo_title = excluded.seo_title, seo_description = excluded.seo_description,
  intended_use = excluded.intended_use, sensory_line = excluded.sensory_line, sensory_notes = excluded.sensory_notes, storage = excluded.storage, shelf_life = excluded.shelf_life, serving = excluded.serving,
  serving_ml = excluded.serving_ml, directions = excluded.directions, how_to = excluded.how_to, updated_at = now();

insert into public.product_variants (product_id, sku, label, size_ml, price_cents, compare_at_cents, is_default, sort_order, image_storage_path, description, stock)
select p.id, v.sku, v.label, v."sizeMl", v.price, v.compare, v.def, v.i, v.image, v."desc", 100
from seed_doc, jsonb_array_elements(d->'products') pr
join public.products p on p.slug = pr->>'slug',
jsonb_to_recordset(pr->'variants') as v(sku text, label text, "sizeMl" numeric, price int, compare int, def bool, i int, image text, "desc" text)
on conflict (sku) do update set product_id = excluded.product_id, label = excluded.label, size_ml = excluded.size_ml, price_cents = excluded.price_cents, compare_at_cents = excluded.compare_at_cents,
  is_default = excluded.is_default, sort_order = excluded.sort_order, image_storage_path = excluded.image_storage_path, description = excluded.description;

-- retire variants that left the catalog (unless an order references them)
delete from public.product_variants pv
where pv.product_id in (select id from public.products where slug in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case'))
  and pv.sku not in (select v->>'sku' from seed_doc, jsonb_array_elements(d->'products') pr, jsonb_array_elements(pr->'variants') v)
  and not exists (select 1 from public.order_items oi where oi.variant_id = pv.id)
  and not exists (select 1 from public.bundle_items bi where bi.variant_id = pv.id);

delete from public.product_images where product_id in (select id from public.products where slug in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case'));
insert into public.product_images (product_id, storage_path, alt, sort_order, aspect)
select p.id, g.path, g.alt, g.i, g.aspect
from seed_doc, jsonb_array_elements(d->'products') pr
join public.products p on p.slug = pr->>'slug',
jsonb_to_recordset(pr->'gallery') as g(path text, alt text, i int, aspect numeric);

delete from public.product_sections where product_id in (select id from public.products where slug in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case'));
insert into public.product_sections (product_id, section_type, content, sort_order)
select p.id, s.t, s.c, s.i
from seed_doc, jsonb_array_elements(d->'products') pr
join public.products p on p.slug = pr->>'slug',
jsonb_to_recordset(pr->'sections') as s(t text, c jsonb, i int);

delete from public.claims where product_id in (select id from public.products where slug in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case'));
insert into public.claims (product_id, text, claim_type, requires_dshea_disclaimer, approved_by, approved_at)
select p.id, c.t, 'spec', false, 'founder', now()
from public.products p, (values
  ('Physician formulated by Dr. Quddarat U. Mushtaq, MD, MS, founder and owner'),
  ('Thymoquinone measured per lot; see the lot certificate'),
  ('Single-origin botanicals, one harvest per lot'),
  ('Third-party tested; certificate of analysis per lot')) as c(t)
where p.slug in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case');

-- "Why it suits your skin": appearance-and-feel statements per hero botanical (product-detail.js).
-- Seeded as approved because the repo copy passes the banned-word check and owner review before merge.
insert into public.claims (product_id, text, claim_type, requires_dshea_disclaimer, approved_by, approved_at)
select p.id, w.t, 'cosmetic', false, 'founder', now()
from seed_doc, jsonb_array_elements(d->'products') pr
join public.products p on p.slug = pr->>'slug',
jsonb_array_elements_text(pr->'why') as w(t);

delete from public.bundle_items where bundle_product_id in (select id from public.products where slug in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case'));
insert into public.bundle_items (bundle_product_id, variant_id, quantity)
select p.id, v.id, b.qty
from seed_doc, jsonb_array_elements(d->'products') pr
join public.products p on p.slug = pr->>'slug',
jsonb_to_recordset(pr->'bundle') as b(sku text, qty int)
join public.product_variants v on v.sku = b.sku;

delete from public.collection_products;
insert into public.collection_products (collection_id, product_id, sort_order)
select c.id, p.id, p.sort_order from public.products p join public.collections c on c.slug = p.collection_slug;

update public.products set is_published = false where slug not in ('blackseed-oil','blackseed-oil-softgels','golden-hour-saffron-infusion','culinary-finishing-oil','rose-blackseed-cleansing-oil','saffron-radiance-face-oil','saffron-blackseed-eye-concentrate','grapevine-renewal-serum','blackseed-balm','amla-blackseed-hair-oil','scalp-beard-serum','blackseed-bath-soak','saffron-sesame-body-oil','oud-noir-attar','kesar-rose-attar','vigne-verte-attar','fragrance-discovery-set','the-travel-ritual','the-morning-protocol','the-skin-ritual','the-hair-ritual','the-founders-set','the-complete-shelf','practitioner-case');
update public.collections set is_published = false where slug not in ('within','skin','hair','body','fragrance','ritual-sets');
